&lt;img src="https://media2.dev.to/dynamic/image/width=150,height=150,fit=cover,gravity=auto,format=auto/https%3A%2F%2Fdev-to-uploads.s3.amazonaws.com%2Fuploads%2Fuser%2Fprofile_image%2F3678447%2F04f0822d-c3a3-4f63-a66f-5344e01a6049.png" alt="shoaibalimir image"&gt;
&lt;/div&gt;
